package org.eclipse.rdf4j.spring.dao.support.joinbuilder.evaluationbuilder.support;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.stream.Collector;
import java.util.stream.Stream;

import org.junit.jupiter.api.Test;

public class CustomCollectorsTests {

	@Test
	public void delegatesEveryCollectorComponent() {
		CustomCollectors<String, List<String>, String> collector = new CustomCollectors<>(
				ArrayList::new,
				List::add,
				(left, right) -> {
					left.addAll(right);
					return left;
				},
				values -> String.join(",", values),
				Set.of(Collector.Characteristics.UNORDERED));

		List<String> accumulator = collector.supplier().get();
		collector.accumulator().accept(accumulator, "Luke");
		assertEquals(List.of("Luke"), accumulator);
		assertEquals(
				List.of("Luke", "Yoda"),
				collector.combiner().apply(accumulator, new ArrayList<>(List.of("Yoda"))));
		assertEquals("Luke,Yoda", collector.finisher().apply(accumulator));
		assertEquals(Set.of(Collector.Characteristics.UNORDERED), collector.characteristics());
	}

	@Test
	public void identityFinisherCollectsAccumulatedValues() {
		CustomCollectors<String, List<String>, List<String>> collector = new CustomCollectors<>(
				ArrayList::new,
				List::add,
				(left, right) -> {
					left.addAll(right);
					return left;
				},
				Set.of());

		assertEquals(List.of("Luke", "Leia"), Stream.of("Luke", "Leia").collect(collector));
		List<String> values = new ArrayList<>(List.of("Luke"));
		assertSame(values, collector.finisher().apply(values));
	}
}
